const fs=require('fs'),crypto=require('crypto'),zlib=require('zlib');const h=x=>crypto.createHash('sha256').update(x).digest('hex');const base='docs/remediation/evidence/W06.11/';const a=JSON.parse(fs.readFileSync(base+'artifact.json','utf8'));const b=JSON.parse(fs.readFileSync('docs/remediation/design/W06.11/baseline.json','utf8'));const d=JSON.parse(fs.readFileSync(base+'source-deltas.json','utf8'));const bad=a.files.filter(p=>h(fs.readFileSync(p.path))!==p.sha256);const own=new Set(b.owned.map(p=>p.path));const protectedPins=b.pins.filter(p=>!own.has(p.path));const protectedBad=protectedPins.filter(p=>h(fs.readFileSync(p.path))!==p.sha256);
function patch(input,diff){const lines=input?input.replace(/
$/,'').split('
'):[],out=[];let pos=0;const ds=diff.split('
');for(let i=0;i<ds.length;i++){const m=ds[i].match(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@/);if(!m)continue;const start=Number(m[1])-(Number(m[2]??1)===0?0:1);if(start<pos)throw Error('overlap');out.push(...lines.slice(pos,start));pos=start;let old=0,next=0;for(i++;i<ds.length&&!ds[i].startsWith('@@ ');i++){const line=ds[i];if(line==='')break;if(line.startsWith('\'))throw Error('newline marker');if(line[0]===' '||line[0]==='-'){if(lines[pos]!==line.slice(1))throw Error('context mismatch');pos++;old++;}if(line[0]===' '||line[0]==='+'){out.push(line.slice(1));next++;}}if(old!==Number(m[2]??1)||next!==Number(m[4]??1))throw Error('count');i--;}out.push(...lines.slice(pos));return out.length?out.join('
')+'
':'';}
const deltaResults=d.deltas.map(x=>{const old=zlib.gunzipSync(Buffer.from(b.owned.find(p=>p.path===x.path).content_gzip_base64,'base64')).toString();const current=fs.readFileSync(x.path,'utf8');return{path:x.path,before:h(old)===x.before_sha256,after:h(current)===x.after_sha256,forward:patch(old,x.forward)===current,reverse:patch(current,x.reverse)===old};});const digest=h(JSON.stringify({contract_digest:a.contract_digest,configuration:a.configuration,files:a.files.map(({path,sha256,role})=>({path,sha256,role})).sort((x,y)=>x.path.localeCompare(y.path))}));console.log(JSON.stringify({at:new Date().toISOString(),artifact_digest:digest,manifest_sha256:h(fs.readFileSync(base+'artifact.json')),pins:a.files.length,bad,protected_count:protectedPins.length,protected_bad:protectedBad,deltas:deltaResults,basis:['docs/remediation/design/W06.11/plan.md',base+'artifact.json',base+'worker.json'].map(path=>({path,sha256:h(fs.readFileSync(path))}))},null,2));if(bad.length||protectedBad.length||deltaResults.some(x=>!x.before||!x.after||!x.forward||!x.reverse)||digest!=='ebc43b31fbc8955ebe9f57b95fecce54c7ad26c065b543a62e4d954d4a3602b5')process.exit(1);
